/**
 * Unit tests for Complex.divide(Complex)
 */
public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testDivide_InfiniteDivisor_FiniteDividend() {
        Complex inf = new Complex(Double.POSITIVE_INFINITY, 0.0);
        Complex c = new Complex(5.0, 5.0);

        // (5+5i) / INF -> 0
        Complex result = c.divide(inf);
        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(0.0, result.getImaginary(), EPSILON);
        assertFalse(result.isInfinite());
        assertFalse(result.isNaN());
    }








}

