/**
 * Unit tests for Complex.divide(Complex)
 */
public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testDivide_Branch_AbsC_LessThan_AbsD() {
        // Real part < Imaginary part
        // divisor: 1 + 2i -> c=1, d=2. |1| < |2| is true.
        Complex dividend = new Complex(10.0, 10.0);
        Complex divisor = new Complex(1.0, 2.0);

        // (10+10i) / (1+2i) = [(10+10i)(1-2i)] / [1^2 + 2^2]
        // = [10 - 20i + 10i - 20i^2] / 5
        // = [10 - 10i + 20] / 5 = (30 - 10i) / 5 = 6 - 2i
        Complex result = dividend.divide(divisor);

        assertEquals(6.0, result.getReal(), EPSILON);
        assertEquals(-2.0, result.getImaginary(), EPSILON);
    }




}

