public class Complex_divide_TriageGen2Test {

    private static final double EPSILON = 1e-10;















    @Test
    public void testDivide_Branch_AbsC_GreaterThan_AbsD() {
        // Real part >= Imaginary part
        // divisor: 2 + 1i -> c=2, d=1. |2| < |1| is false.
        Complex dividend = new Complex(10.0, 10.0);
        Complex divisor = new Complex(2.0, 1.0);

        // (10+10i) / (2+i) = [(10+10i)(2-i)] / [2^2 + 1^2]
        // = [20 - 10i + 20i - 10i^2] / 5
        // = [20 + 10i + 10] / 5 = (30 + 10i) / 5 = 6 + 2i
        Complex result = dividend.divide(divisor);

        assertEquals(6.0, result.getReal(), EPSILON);
        assertEquals(2.0, result.getImaginary(), EPSILON);
    }


}

