    public void testDivide_Branch_AbsC_Equals_AbsD() {
        // Real part == Imaginary part
        // divisor: 1 + 1i -> c=1, d=1. |1| < |1| is false.
        Complex dividend = new Complex(2.0, 4.0);
        Complex divisor = new Complex(1.0, 1.0);

        // (2+4i) / (1+i) = [(2+4i)(1-i)] / 2
        // = [2 - 2i + 4i - 4i^2] / 2
        // = [2 + 2i + 4] / 2 = (6 + 2i) / 2 = 3 + i
        Complex result = dividend.divide(divisor);

        assertEquals(3.0, result.getReal(), EPSILON);
        assertEquals(1.0, result.getImaginary(), EPSILON);
    }
